import{z as B,x as s,o as a,c as d,q as n,j as t,D as i,d as r,s as A,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"io_uring","description":"","frontmatter":{"title":"io_uring","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hpc-io-uring.md","filePath":"cs/hpc-io-uring.md","lastUpdated":1791063341000}'),p={name:"cs/hpc-io-uring.md"};function u(c,e,_,C,h,g){const o=s("Mermaid");return a(),d("div",null,[e[2]||(e[2]=n('<h1 id="io-uring" tabindex="-1">io_uring <a class="header-anchor" href="#io-uring" aria-label="Permalink to &quot;io_uring&quot;">​</a></h1><div class="epigraph"><p>就绪通知回答「现在能做吗」，提交完成回答「帮我做完」；从前者换到后者，省的是每个事件陪跑的那一次陷入。</p><footer>—— 据 Axboe, *Efficient IO with io_uring*, 2019；liburing 手册整理</footer></div><p><a href="/cs/hpc-epoll-deep">上一课</a>把事件循环分片、治理了惊群、把定时与唤醒并进一个 wait，但模型仍是就绪通知：wait 说可读，应用还得再发一次 read。<a href="/cs/io-uring">io_uring</a> 已在主干钉了共享 SQ/CQ 环的骨架与 VFS 侧的语义；本课深化的是把它当网络 I/O 模型用时的账——每事件系统调用数怎么降、哪些特性在哪个内核版本才有、什么负载其实不受益。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>就绪通知的每事件下界是两次陷入：一次 wait，一次 read/write。事件率到百万级每秒时，陷入与上下文切换本身占掉可观 CPU，<a href="/cs/hpc-epoll-deep">上一课</a>末尾正是把这一点留作缺口。io_uring 的 SQE 与 CQE 都在共享内存上：一次 <code>io_uring_enter</code> 提交一批、收割一批，摊销后每事件不足一次陷入；SQPOLL 模式由内核线程轮询 SQ，连 enter 都省掉。不这么做会错在哪：把它当「快版 epoll」，只是把 recv 换成异步写法，每事件仍是提交一次、收割一次、等待一次，摊销没有发生；或者提交后不等 CQE 就复用缓冲，内核把数据写进你已经开始改写的页。</p><p><span class="marginnote">直觉类比：就绪通知像外卖到了只发短信「可以取了」，你还得自己跑一趟（read）；io_uring 像跟代收点说「这十单都帮我收好」，一次出门全提回来——出门次数（陷入）被批量摊薄。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>网络化的关键特性有四件。multishot accept：一次提交长期收割新连接，不必每条连接重新提交；multishot recv：内核把就绪数据直接随 CQE 附带缓冲送达，省去逐次提交读请求；注册缓冲与注册文件表把 fd 数组与缓冲池钉在内核，免掉每次引用计数；<code>IOSQE_IO_LINK</code> 把 accept → recv → send 串成链，一批 enter 全部下发，依赖由内核保证顺序。发送用 SEND，配 SEND_ZC 走零拷贝路径。基本循环：填一批 SQE → enter 提交并顺带收割 → 处理 CQE → 循环；SQPOLL 打开后提交侧无系统调用。</p>',8)),(a(),t(l,null,{default:i(()=>[A(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E5%A1%AB%E4%B8%80%E6%89%B9%20SQE%22%5D%20--%3E%20SQ%5B%22SQ%20%E7%8E%AF%EF%BC%88%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98%EF%BC%89%22%5D%0A%20%20SQ%20--%3E%20ENTER%5B%22io_uring_enter%20%E6%8F%90%E4%BA%A4%E5%B9%B6%E6%94%B6%E5%89%B2%22%5D%0A%20%20SQ%20--%3E%20SP%5B%22SQPOLL%EF%BC%9A%E5%86%85%E6%A0%B8%E7%BA%BF%E7%A8%8B%E8%BD%AE%E8%AF%A2%20SQ%22%5D%0A%20%20ENTER%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E6%89%A7%E8%A1%8C%20ACCEPT%2FRECV%2FSEND%22%5D%0A%20%20SP%20--%3E%20K%0A%20%20K%20--%3E%20CQ%5B%22CQ%20%E7%8E%AF%EF%BC%9Acqe%20%E6%90%BA%E5%B8%A6%E7%BB%93%E6%9E%9C%22%5D%0A%20%20CQ%20--%3E%20REAP%5B%22%E5%BA%94%E7%94%A8%E6%89%B9%E9%87%8F%E6%94%B6%E5%89%B2%20CQE%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("p",null,"收益按来源分解：环消除参数拷贝，批量消除陷入次数，注册表消除 fd 引用管理，完成模型消除「就绪但 EAGAIN」的竞态——提交的就是具体请求，短读短写以 cqe 的结果字段表达，不在 errno 里。不受益的负载同样要认清：低事件率时环的固定成本没有对手可摊；单连接大文件顺序读写本来陷入就不占大头。版本账必须对表：io_uring 自 5.1 进主线，multishot、SEND_ZC、SQPOLL 的可用性与成熟度散布在 5.19、6.0 及以后，按目标内核逐项核对再设计。安全面也是账目的一部分：内核漏洞频发，Google 已宣布自 Android 14 起收紧 io_uring，把它当攻击面来管理，不是一句「性能更好」能带过的。",-1)),e[5]||(e[5]=E("p",null,"两种模型每事件的陷入对账：",-1)),(a(),t(l,null,{default:i(()=>[A(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22epoll%20%E5%B0%B1%E7%BB%AA%E9%80%9A%E7%9F%A5%22%5D%20--%3E%20W1%5B%22wait%3A%20%E7%AC%AC%201%20%E6%AC%A1%E9%99%B7%E5%85%A5%22%5D%0A%20%20W1%20--%3E%20R%5B%22read%2Fwrite%3A%20%E7%AC%AC%202%20%E6%AC%A1%E9%99%B7%E5%85%A5%22%5D%0A%20%20R%20--%3E%20N%5B%22%E4%B8%8B%E4%B8%80%E4%BA%8B%E4%BB%B6%E5%86%8D%E9%87%8D%E6%9D%A5%E4%B8%80%E9%81%8D%22%5D%0A%20%20U%5B%22io_uring%20%E6%8F%90%E4%BA%A4%E5%AE%8C%E6%88%90%22%5D%20--%3E%20B%5B%22%E4%B8%80%E6%89%B9%20SQE%20%E4%B8%80%E6%AC%A1%20enter%22%5D%0A%20%20B%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E5%81%9A%E5%AE%8C%2C%20%E7%BB%93%E6%9E%9C%E8%BF%9B%20CQ%22%5D%0A%20%20K%20--%3E%20M%5B%22N%20%E4%B8%AA%E4%BA%8B%E4%BB%B6%E6%91%8A%E4%B8%80%E6%AC%A1%E9%99%B7%E5%85%A5%22%5D%0A%20%20M%20--%3E%20Z%5B%22SQPOLL%3A%20%E6%8F%90%E4%BA%A4%E4%BE%A7%200%20%E6%AC%A1%E9%99%B7%E5%85%A5%22%5D%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<p><span class="marginnote">数字实例：epoll 模式百万事件每秒约 200 万次陷入；io_uring 一次 enter 提交并收割各 256 个事件，陷入降到约 4000 次；SQPOLL 打开后提交侧归零——这就是「每事件不足一次陷入」的算术。</span></p><p><span class="marginnote">一次 enter 可提交与收割各数百个 SQE/CQE，摊销系数随批次走；SQPOLL 空转也烧 CPU，生产上按事件率动态开关，或配 <code>sq_thread_idle</code> 让内核线程空闲后让出。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写文件 I/O 与页缓存的交互（主干 <a href="/cs/io-uring">io_uring</a> 已及 VFS 权限与 bio 路径），不写 eBPF 与 io_uring 的组合。当包率高到一次陷入都嫌多、连 VFS 层都想跳过时，路径要从协议栈整体拿掉——内核旁路是下一课。</p><p><span class="marginnote">常见误区：以为 io_uring 对所有负载都快。低事件率时环的建立与固定成本没人摊；单连接顺序读写本来陷入就不占大头——它省的是「每事件陪跑的陷入」，你的负载若没有这笔账，就享受不到这笔折扣。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>就绪通知每事件两次陷入；提交完成摊销后不足一次，SQPOLL 可到零。</li><li>multishot、链接 SQE、注册缓冲与文件是网络化的关键特性，按内核版本对表启用。</li><li>完成模型消除就绪-读取竞态，短读短写在 cqe 结果里，不在 errno 里。</li><li>低事件率与单连接负载不受益；io_uring 同时是一张需要管理的内核攻击面。</li><li>出处：Axboe, <em>Efficient IO with io_uring</em>（2019）；liburing 与 Linux 内核 io_uring 文档。</li></ul>',7))])}const Q=B(p,[["render",u]]);export{m as __pageData,Q as default};
